export default {"labsPage":{"decisionAssistance":{"title":"Assistència per a la presa de decisions","description":"Activa l'assistència experimental del model de decisió que has configurat.","optedIn":"Preferència desada.","loading":"S’està carregant la configuració…","unavailable":"No s’ha pogut carregar aquesta configuració. Torna a connectar-te o actualitza per tornar-ho a provar.","refresh":"Actualitza la configuració"},"usageRankedToolIndex":{"title":"Índex d'eines ordenat segons l'ús","description":"Prioritza les eines utilitzades més sovint i més recentment als índexs de prompts de Code Mode, Tool Search i el directori d’eines MCP. Desactivat per defecte. Desa els identificadors de les eines, les puntuacions i les marques de temps durant 90 dies en un emmagatzematge propietat de l’operador, excloent-ne les sessions d’incògnit. Els canvis s’apliquen al límit següent del prefix del prompt. Inspecciona, importa o restableix les dades amb openclaw tools usage."},"codeMode":{"title":"Mode de codi","description":"Estableix el valor global per defecte per als fluxos de treball compactes amb eines JavaScript. Activat selecciona Auto per als models avaluats; Desactivat desactiva el valor per defecte. Les excepcions del mode de codi per model són a Valors per defecte de l’agent → Models (Avançat).","executor":"Executor del mode de codi","executorDescription":"Node.js està pensat per a codi de confiança; la seva màquina virtual no és un entorn aïllat de seguretat. QuickJS executa el codi en un entorn d’execució WebAssembly aïllat. Les crides a través de les eines d’OpenClaw utilitzen els mateixos permisos. S’aplica a les respostes noves; les configuracions específiques dels agents tenen prioritat.","executorNode":"Node.js (per defecte)","executorQuickjs":"QuickJS (aïllat)"},"swarm":{"groupTitle":"Tasques en paral·lel","progress":"{complete} de {total}","active":"{running} en execució · {queued} a la cua · {failed} fallides o aturades","finished":"{done} completades · {failed} fallides o aturades","completed":"{done} completades","failedOrStopped":"Fallides o aturades","childOutcome":"Els subagents han acabat. Consulta la conversa per veure la resposta final.","childOutcomeProcessing":"Els subagents han acabat. L’agent principal està processant els seus resultats.","details":"Detalls dels subagents","detailsUnavailable":"Els detalls dels subagents no estan disponibles. Els recomptes inclouen tots els subagents acceptats.","otherGroups":"{count} grups actius més"},"toolSearch":{"title":"Cerca d’eines per a tots els models","description":"Ajornament de la càrrega dels esquemes d'eines i descoberta d'eines sota demanda. Activat per defecte amb crides estructurades a eines; si es desactiva, es desactiva el valor predeterminat global."},"hostDesktop":{"title":"Escriptori de l’ordinador on s’executa OpenClaw","description":"Visualitza i controla l’ordinador on s’executa OpenClaw des del tauler Escriptori mitjançant el seu servidor VNC o de compartició de pantalla existent."},"openclawId":{"title":"Accés remot amb OpenClaw ID","description":"Obre aquest claw des dels teus altres dispositius i convida-hi altres persones. Per començar, inicia la sessió des del menú del compte i tria Activa l'accés remot. Gestiona qui hi té accés a la pàgina Accés. Mentre està desactivada, aquesta funció no contacta amb OpenClaw ID."},"workerDesktop":{"title":"Escriptori del dispositiu al núvol","description":"Visualitza i controla els escriptoris dels dispositius al núvol des de perfils de Crabbox AWS, Azure o Hetzner amb la compatibilitat amb l’escriptori activada."},"composerPredictions":{"title":"Prediccions del redactor","description":"Suggereix el missatge següent després d'una resposta a la conversa activa. Afegeix una crida al model sense eines amb el context de la conversa. La tecla de tabulació incorpora el suggeriment a l'esborrany; mai no l'envia automàticament. Desactivat per defecte.","model":"Model de predicció","modelDescription":"Utilitat fa servir el model d'utilitat de l'agent i pot provar els models alternatius que té configurats. Sessió fa servir el model de la sessió actual; Per defecte fa servir el model principal configurat de l'agent. Sense un model d'utilitat, Utilitat omet les prediccions.","utility":"Model auxiliar (recomanat)","conversation":"Model de la sessió","default":"Model predeterminat"},"chatBubbles":{"title":"Bombolles de conversa","description":"Prova les bombolles de conversa amb l'activitat de les eines en format compacte. Mentre aquesta funció estigui activada, l'inici fa servir bombolles per defecte; cada navegador conserva les preferències de conversa seleccionades explícitament. Desactivar aquesta funció experimental restaura la vista estàndard sense esborrar aquestes preferències."},"templates":{"title":"Plantilles","description":"Les plantilles són agents preconfigurats per a tasques específiques."}}};
